 const vp=page.locator('.ll-scan-viewport');await vp.scrollIntoViewIfNeeded();const target=page.locator(sel('hotspot','[data-id="title"]'));await target.scrollIntoViewIfNeeded();const before=await scanState(page),b=await target.boundingBox(),cx=b.x+b.width*.5,cy=b.y+b.height*.5;
