 await driver.send('touchStart',[{x:cx-r0,y:cy},{x:cx+r0,y:cy}]);for(let i=1;i<=10;i++){const r=r0+(r1-r0)*i/10;await driver.send('touchMove',[{x:cx-r,y:cy},{x:cx+r,y:cy}]);}await driver.send('touchEnd',[]);
 await waitFrame(page);
 const after=await scanState(page);rec.pagePinch.after=after;assert.equal(after.zoom,before.zoom,'Two fingers must not change separate scan zoom');assert.deepEqual(after.selected,before.selected,'Page pinch cannot select an answer');
