 assert.ok(rec.touchSamples.some(e=>e.type==='touchmove'&&e.touches.length===2&&e.trusted===(rec.engine==='chromium')&&e.action==='hotspot'),'Nonempty two-finger samples target the real answer region with the declared trust');assert.ok(rec.touchSamples.filter(e=>e.type.startsWith('touch')).every(e=>!e.cancelled),'The product must not cancel native touch gestures');rec.screenshot=await shot(page,rec.id);
