 assert.ok(appearance,'Dock, inner paper and check button are present');assert.equal(appearance.dockPosition,'sticky');assert.ok(['auto','scroll'].includes(appearance.overflowY));assert.ok(appearance.paperHeight>0&&appearance.paperScrollHeight>appearance.paperHeight,'A complete long document has a real inner scroll area');assert.equal(appearance.touchAction,appearance.touchActionSupported?'auto':'','Touch gesture policy is native auto where supported, otherwise an explicitly unsupported property');assert.equal(appearance.overscrollY,appearance.overscrollSupported?'auto':'','Scroll chaining policy is auto where supported; actual inner/gutter wheel behavior is checked separately');assert.equal(appearance.checkText,'✔');assert.equal(appearance.checkColor,'rgb(255, 255, 255)');assert.ok(/^rgb\(/.test(appearance.checkBackground)&&Number(appearance.checkBackground.match(/\d+/g)[2])>Number(appearance.checkBackground.match(/\d+/g)[0]),'Check icon is white on a blue background');return {groups:groups.map(g=>({docId:g.docId,questions:g.tasks.map(x=>x.task.id)})),appearance};
