async function canvasSourceProof(page,scan,{hidden}){
 const image=page.locator('canvas[data-type-image="'+scan.id+'"][data-image-ready="true"]');await image.waitFor({state:'attached'});
 const proof=await image.evaluate(async(el,{url,region,hidden})=>{const bitmap=await createImageBitmap(await(await fetch(url)).blob()),reference=document.createElement('canvas');reference.width=el.width;reference.height=el.height;reference.getContext('2d').drawImage(bitmap,0,0,el.width,el.height);const expected=reference.getContext('2d').getImageData(0,0,el.width,el.height).data,actual=el.getContext('2d').getImageData(0,0,el.width,el.height).data,bounds={left:region[0]*el.width,top:region[1]*el.height,right:(region[0]+region[2])*el.width,bottom:(region[1]+region[3])*el.height};let outside=0,outsideMatches=0,inside=0,insideDifferences=0,insideUniform=true,firstColor=null;for(let y=0;y<el.height;y++)for(let x=0;x<el.width;x++){const i=(y*el.width+x)*4,same=actual[i]===expected[i]&&actual[i+1]===expected[i+1]&&actual[i+2]===expected[i+2]&&actual[i+3]===expected[i+3];if(x<bounds.left-2||x>bounds.right+2||y<bounds.top-2||y>bounds.bottom+2){outside++;if(same)outsideMatches++;}else if(x>bounds.left+2&&x<bounds.right-2&&y>bounds.top+2&&y<bounds.bottom-2){inside++;if(!same)insideDifferences++;const color=[actual[i],actual[i+1],actual[i+2],actual[i+3]].join(',');firstColor??=color;if(color!==firstColor)insideUniform=false;}}return {source:url,id:el.dataset.typeImage,connected:el.isConnected,ready:el.dataset.imageReady,revealed:el.dataset.typeRevealed,width:el.width,height:el.height,naturalWidth:bitmap.width,naturalHeight:bitmap.height,outside,outsideMatches,inside,insideDifferences,insideUniform,hidden};},{url:new URL('/apps/legal-lab/'+scan.image,page.url()).href,region:scan.hotspots.find(h=>h.id==='type').rect,hidden});
 assert.equal(proof.id,scan.id);assert.equal(proof.connected,true);assert.equal(proof.ready,'true');assert.equal(proof.width,proof.naturalWidth);assert.equal(proof.height,proof.naturalHeight);assert.ok(proof.outside>0&&proof.inside>0);assert.equal(proof.outsideMatches,proof.outside,'Canvas contains actual source pixels outside the type mask');if(hidden){assert.equal(proof.revealed,'false');assert.equal(proof.insideUniform,true,'The mask is burned into canvas pixels, not only a removable DOM overlay');assert.ok(proof.insideDifferences>0,'The underlying type line differs from the unmasked source');}else{assert.equal(proof.revealed,'true');assert.equal(proof.insideDifferences,0,'An exact checked answer reveals the authentic source pixels');}return proof;
}
